package dev.hrutvik.billing.invoice;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import dev.hrutvik.billing.outbox.*; import dev.hrutvik.billing.rating.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service
public class InvoiceService {
 private final InvoiceStore invoices; private final RatingService rating; private final OutboxEventRepository outbox; private final ObjectMapper json; private final Clock clock;
 public InvoiceService(InvoiceStore invoices,RatingService rating,OutboxEventRepository outbox,ObjectMapper json){this(invoices,rating,outbox,json,Clock.systemUTC());} InvoiceService(InvoiceStore i,RatingService r,OutboxEventRepository o,ObjectMapper j,Clock c){invoices=i;rating=r;outbox=o;json=j;clock=c;}
 @Transactional public InvoiceResponse finalizePeriod(String tenantId,UUID subscriptionId,Instant from,Instant to){if(!from.isBefore(to))throw new IllegalArgumentException("period start must be before end");invoices.lockSubscription(tenantId,subscriptionId);var existing=invoices.existing(tenantId,subscriptionId,from,to);if(existing.isPresent())return existing.get();var preview=rating.preview(tenantId,subscriptionId,from,to);UUID id=UUID.randomUUID();String number="INV-"+id.toString().substring(0,8).toUpperCase(Locale.ROOT);Instant now=clock.instant();invoices.insertInvoice(id,number,tenantId,subscriptionId,preview.currency(),from,to,preview.total(),now);var views=new ArrayList<InvoiceLineView>();try{for(var line:preview.lines()){invoices.insertLine(UUID.randomUUID(),id,line.meterKey(),line.quantity(),line.amount(),json.writeValueAsString(Map.of("meterKey",line.meterKey(),"tiers",line.appliedTiers(),"rounding","HALF_UP","scale",2)));views.add(new InvoiceLineView(line.meterKey(),line.quantity(),line.amount()));}outbox.save(new OutboxEvent(UUID.randomUUID(),id,"INVOICE_FINALIZED",tenantId,"billing.invoice-finalized.v1",json.writeValueAsString(Map.of("invoiceId",id,"invoiceNumber",number,"total",preview.total(),"currency",preview.currency())),now));}catch(JsonProcessingException e){throw new IllegalStateException("Could not snapshot invoice pricing",e);}return new InvoiceResponse(id,number,subscriptionId,preview.currency(),from,to,preview.total(),"FINALIZED",List.copyOf(views),false);}
}
